        var mode=context.computeOnClient(client->{var screen=(ElevatorContactScreen)client.gui.screen();var widget=screen.children().stream().filter(Button.class::isInstance).map(Button.class::cast).filter(button->button.getWidth()==216).findFirst().orElseThrow();float scaleX=(float)client.getWindow().getScreenWidth()/client.getWindow().getGuiScaledWidth();float scaleY=(float)client.getWindow().getScreenHeight()/client.getWindow().getGuiScaledHeight();return new Vec2((widget.getX()+widget.getWidth()/2f)*scaleX,(widget.getY()+10)*scaleY);});context.getInput().setCursorPos(mode.x,mode.y);context.getInput().scroll(-1);context.runOnClient(client->{if(((ElevatorContactScreen)client.gui.screen()).doorMode()!=DoorControl.NONE)throw new AssertionError("Actual native contact wheel failed to select NONE");});screenshot(context,"create-vulkan-elevator-native-floor-name-description-and-arrival-door-screen");context.clickScreenButton("✓");context.waitFor(client->client.gui.screen()==null,200);waitServer(context,world,level->level.getBlockEntity(LOWER) instanceof ElevatorContactBlockEntity floor&&floor.shortName.equals("L")&&floor.longName.equals("Lower deck")&&floor.doorControls.mode==DoorControl.NONE,250,"Confirmed native floor editor did not persist exact source label/door mode");
