        var old=context.computeOnClient(client->client.getModelManager().getModel(AllPartialModels.ELEVATOR_COIL));var reload=context.computeOnClient(Minecraft::reloadResourcePacks);context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);reload.join();context.runOnClient(client->{if(client.getModelManager().getModel(AllPartialModels.ELEVATOR_COIL)==old)throw new AssertionError("Native elevator coil retained stale resource-reload geometry");});verifyRenderer(context);screenshot(context,"create-vulkan-elevator-native-coil-belt-magnet-after-resource-reload");
